local VirtualLiveTile = {}function VirtualLiveTile:new(init)  print("[VirtualLiveTile]: new()")  local o = {    loc = init.loc,    im = init.im,    bindingName = init.bindingName,    headline = init.headline,    subHeadline = init.subHeadline,    description = init.description,    status = init.status,    images = init.images,    feedback = init.feedback  }  setmetatable(o, self)  self.__index = self  if o.status == "new" then    o.statusText = o.loc.LocalizeString("LTXT_LIVE_TILE_STATUS_NEW")  elseif o.status == "completed" then    o.statusText = o.loc.LocalizeString("LTXT_LIVE_TILE_STATUS_COMPLETED")  elseif o.status == "sale" then    o.statusText = o.loc.LocalizeString("LTXT_LIVE_TILE_STATUS_SALE")  else    o.statusText = nil  end  o.liveData = {    headline = o.headline,    subHeadline = o.subHeadline,    description = o.description,    status = o.status,    statusText = o.statusText,    images = o.images,    feedback = o.feedback  }  return oendfunction VirtualLiveTile:publish()  print("[VirtualLiveTile]: publish()")  self.im.Publish(self.bindingName, self.liveData)endreturn VirtualLiveTile